function normalizePath(path) {
  const segs = [];
  for (const seg of path.split('/')) {
    if (seg === '..') segs.pop();
    else if (seg !== '.' && seg !== '') segs.push(seg);
  }
  return '/' + segs.join('/') + (path.endsWith('/') && segs.length ? '/' : '');
